-- Additiva Valagården-kompletteringar från masterfilen 2026-09-01.
-- Befintliga arrayposter bevaras; identiska tillägg läggs inte in igen.
begin;

create or replace function pg_temp.append_unique_jsonb_array(base jsonb, additions jsonb)
returns jsonb
language sql
immutable
as $$
  select coalesce(jsonb_agg(value order by first_position), '[]'::jsonb)
  from (
    select value, min(position) as first_position
    from (
      select value, ordinality::bigint as position
      from jsonb_array_elements(coalesce(base, '[]'::jsonb)) with ordinality
      union all
      select value, 1000000 + ordinality::bigint as position
      from jsonb_array_elements(coalesce(additions, '[]'::jsonb)) with ordinality
    ) combined
    group by value
  ) unique_values;
$$;

-- marten_andersson_1701
update public.people set content = jsonb_set(jsonb_set(jsonb_set(coalesce(content, '{}'::jsonb), '{facts}', pg_temp.append_unique_jsonb_array(coalesce(content, '{}'::jsonb)->'facts', '[["Vigselnotis 1731","Mårten anges som dräng i Träslöfs by; notisen innehåller inget säkert Valagårdsbelägg."],["Husförhör ca 1756-1759","Mårtens familj står under gårdsrubriken Jon Nilsgård tillsammans med ett separat hushåll för Börge Andersson."],["Korrigerad läsning","Den femåriga personen i N:o 42-materialet omkring 1700 är Kirsti/Kerstin Andersdotter, inte Mårten Andersson."]]'::jsonb), true), '{story}', pg_temp.append_unique_jsonb_array(jsonb_set(coalesce(content, '{}'::jsonb), '{facts}', pg_temp.append_unique_jsonb_array(coalesce(content, '{}'::jsonb)->'facts', '[["Vigselnotis 1731","Mårten anges som dräng i Träslöfs by; notisen innehåller inget säkert Valagårdsbelägg."],["Husförhör ca 1756-1759","Mårtens familj står under gårdsrubriken Jon Nilsgård tillsammans med ett separat hushåll för Börge Andersson."],["Korrigerad läsning","Den femåriga personen i N:o 42-materialet omkring 1700 är Kirsti/Kerstin Andersdotter, inte Mårten Andersson."]]'::jsonb), true)->'story', '["Valagården-mastern avgränsar den säkra gårdskopplingen noggrant: vigseln 1731 visar bara Mårten som dräng i Träslöfs by. Husförhöret omkring 1756-1759 och originalhandlingarna från 1762 ger däremot starka belägg för familjen vid Jon/Jöns Nilsgård."]'::jsonb), true), '{sources}', pg_temp.append_unique_jsonb_array(jsonb_set(jsonb_set(coalesce(content, '{}'::jsonb), '{facts}', pg_temp.append_unique_jsonb_array(coalesce(content, '{}'::jsonb)->'facts', '[["Vigselnotis 1731","Mårten anges som dräng i Träslöfs by; notisen innehåller inget säkert Valagårdsbelägg."],["Husförhör ca 1756-1759","Mårtens familj står under gårdsrubriken Jon Nilsgård tillsammans med ett separat hushåll för Börge Andersson."],["Korrigerad läsning","Den femåriga personen i N:o 42-materialet omkring 1700 är Kirsti/Kerstin Andersdotter, inte Mårten Andersson."]]'::jsonb), true), '{story}', pg_temp.append_unique_jsonb_array(jsonb_set(coalesce(content, '{}'::jsonb), '{facts}', pg_temp.append_unique_jsonb_array(coalesce(content, '{}'::jsonb)->'facts', '[["Vigselnotis 1731","Mårten anges som dräng i Träslöfs by; notisen innehåller inget säkert Valagårdsbelägg."],["Husförhör ca 1756-1759","Mårtens familj står under gårdsrubriken Jon Nilsgård tillsammans med ett separat hushåll för Börge Andersson."],["Korrigerad läsning","Den femåriga personen i N:o 42-materialet omkring 1700 är Kirsti/Kerstin Andersdotter, inte Mårten Andersson."]]'::jsonb), true)->'story', '["Valagården-mastern avgränsar den säkra gårdskopplingen noggrant: vigseln 1731 visar bara Mårten som dräng i Träslöfs by. Husförhöret omkring 1756-1759 och originalhandlingarna från 1762 ger däremot starka belägg för familjen vid Jon/Jöns Nilsgård."]'::jsonb), true)->'sources', '["Träslöv (N) CI:4, Bild 1410 / Sida 267; Himle häradsrätt FIIb:3, originalsid 9."]'::jsonb), true) where id = 'marten_andersson_1701';

