-- bengt_a_nilsson
update public.people set content = jsonb_set(jsonb_set(jsonb_set(jsonb_set(coalesce(content, '{}'::jsonb), '{facts}', pg_temp.append_unique_jsonb_array(coalesce(content, '{}'::jsonb)->'facts', '[["Namnform i Valagården-mastern","Bengt August Nilsson; webbplatsens befintliga namnform Bengt A. Nilsson behålls tills fullständigt namn är slutligt samordnat mellan källorna."],["Delägare 1866","Familjens avskrift om Träslöv 5:6 beskriver Bengt August Nilsson som delägare i gårdens byggnader, sannolikt den kvarboende parten."],["Skuldebrev 1901","Lån på 1 600 kronor till J. O. Reis med sex procents ränta; årliga räntebetalningar kan följas 1902-1911."],["Valagård 1915","Lokalundersökningsblanketten anger Bengt Nilsson d.ä. som ägare/uppgiftslämnare för det 12 hektar stora jordbruket."],["Äganderätt","Handlingarna ger stark gårdskoppling men varje historisk mantalsandel och fastighetsdel måste fortfarande hållas isär."]]'::jsonb), true), '{story}', pg_temp.append_unique_jsonb_array(jsonb_set(coalesce(content, '{}'::jsonb), '{facts}', pg_temp.append_unique_jsonb_array(coalesce(content, '{}'::jsonb)->'facts', '[["Namnform i Valagården-mastern","Bengt August Nilsson; webbplatsens befintliga namnform Bengt A. Nilsson behålls tills fullständigt namn är slutligt samordnat mellan källorna."],["Delägare 1866","Familjens avskrift om Träslöv 5:6 beskriver Bengt August Nilsson som delägare i gårdens byggnader, sannolikt den kvarboende parten."],["Skuldebrev 1901","Lån på 1 600 kronor till J. O. Reis med sex procents ränta; årliga räntebetalningar kan följas 1902-1911."],["Valagård 1915","Lokalundersökningsblanketten anger Bengt Nilsson d.ä. som ägare/uppgiftslämnare för det 12 hektar stora jordbruket."],["Äganderätt","Handlingarna ger stark gårdskoppling men varje historisk mantalsandel och fastighetsdel måste fortfarande hållas isär."]]'::jsonb), true)->'story', '["Valagården-mastern ger Bengt August Nilsson en betydligt tydligare gårdshistoria. Familjens avskrift av förrättningen 1866 beskriver honom som delägare i husen på Träslöv 5:6 och talar sannolikt för att han var den kvarboende parten när Petter Anders Svensson flyttade ut.","Ett skuldebrev från 1901 visar Bengt August under adressen nr 5 Träslöv med en skuld på 1 600 kronor och sex procents ränta. Räntebetalningar är noterade från 1902 till 1911. Säkerheten var indirekt knuten till 3/64 mantal Jöns Nilsgård, men handlingen visar inte ensam att Bengt August ägde just den intecknade andelen.","År 1915 står Bengt Nilsson den äldre som ägare eller uppgiftslämnare för Valagård i lokalundersökningen. Gården omfattade 12 hektar och var nästan helt uppodlad."]'::jsonb), true), '{timeline}', pg_temp.append_unique_jsonb_array(jsonb_set(jsonb_set(coalesce(content, '{}'::jsonb), '{facts}', pg_temp.append_unique_jsonb_array(coalesce(content, '{}'::jsonb)->'facts', '[["Namnform i Valagården-mastern","Bengt August Nilsson; webbplatsens befintliga namnform Bengt A. Nilsson behålls tills fullständigt namn är slutligt samordnat mellan källorna."],["Delägare 1866","Familjens avskrift om Träslöv 5:6 beskriver Bengt August Nilsson som delägare i gårdens byggnader, sannolikt den kvarboende parten."],["Skuldebrev 1901","Lån på 1 600 kronor till J. O. Reis med sex procents ränta; årliga räntebetalningar kan följas 1902-1911."],["Valagård 1915","Lokalundersökningsblanketten anger Bengt Nilsson d.ä. som ägare/uppgiftslämnare för det 12 hektar stora jordbruket."],["Äganderätt","Handlingarna ger stark gårdskoppling men varje historisk mantalsandel och fastighetsdel måste fortfarande hållas isär."]]'::jsonb), true), '{story}', pg_temp.append_unique_jsonb_array(jsonb_set(coalesce(content, '{}'::jsonb), '{facts}', pg_temp.append_unique_jsonb_array(coalesce(content, '{}'::jsonb)->'facts', '[["Namnform i Valagården-mastern","Bengt August Nilsson; webbplatsens befintliga namnform Bengt A. Nilsson behålls tills fullständigt namn är slutligt samordnat mellan källorna."],["Delägare 1866","Familjens avskrift om Träslöv 5:6 beskriver Bengt August Nilsson som delägare i gårdens byggnader, sannolikt den kvarboende parten."],["Skuldebrev 1901","Lån på 1 600 kronor till J. O. Reis med sex procents ränta; årliga räntebetalningar kan följas 1902-1911."],["Valagård 1915","Lokalundersökningsblanketten anger Bengt Nilsson d.ä. som ägare/uppgiftslämnare för det 12 hektar stora jordbruket."],["Äganderätt","Handlingarna ger stark gårdskoppling men varje historisk mantalsandel och fastighetsdel måste fortfarande hållas isär."]]'::jsonb), true)->'story', '["Valagården-mastern ger Bengt August Nilsson en betydligt tydligare gårdshistoria. Familjens avskrift av förrättningen 1866 beskriver honom som delägare i husen på Träslöv 5:6 och talar sannolikt för att han var den kvarboende parten när Petter Anders Svensson flyttade ut.","Ett skuldebrev från 1901 visar Bengt August under adressen nr 5 Träslöv med en skuld på 1 600 kronor och sex procents ränta. Räntebetalningar är noterade från 1902 till 1911. Säkerheten var indirekt knuten till 3/64 mantal Jöns Nilsgård, men handlingen visar inte ensam att Bengt August ägde just den intecknade andelen.","År 1915 står Bengt Nilsson den äldre som ägare eller uppgiftslämnare för Valagård i lokalundersökningen. Gården omfattade 12 hektar och var nästan helt uppodlad."]'::jsonb), true)->'timeline', '[["1866-07-04","Familjens avskrift beskriver delning av gårdens byggnader mellan Petter Anders Svensson och Bengt August Nilsson."],["1901-04-04","Utfärdar skuldebrev på 1 600 kronor till J. O. Reis."],["1902-1911","Årliga räntebetalningar antecknas på skuldebrevet."],["1915-08-31","Anges som ägare/uppgiftslämnare för Valagård i lokalundersökningen."]]'::jsonb), true), '{sources}', pg_temp.append_unique_jsonb_array(jsonb_set(jsonb_set(jsonb_set(coalesce(content, '{}'::jsonb), '{facts}', pg_temp.append_unique_jsonb_array(coalesce(content, '{}'::jsonb)->'facts', '[["Namnform i Valagården-mastern","Bengt August Nilsson; webbplatsens befintliga namnform Bengt A. Nilsson b