-- sara_britta_andersdotter
update public.people set content = jsonb_set(jsonb_set(coalesce(content, '{}'::jsonb), '{facts}', pg_temp.append_unique_jsonb_array(coalesce(content, '{}'::jsonb)->'facts', '[["Valagård 1915","Maken Bengt Nilsson d.ä. står i lokalundersökningens ägarfält; blanketten avgör inte om Sara Britta hade juridisk deläganderätt."]]'::jsonb), true), '{story}', pg_temp.append_unique_jsonb_array(jsonb_set(coalesce(content, '{}'::jsonb), '{facts}', pg_temp.append_unique_jsonb_array(coalesce(content, '{}'::jsonb)->'facts', '[["Valagård 1915","Maken Bengt Nilsson d.ä. står i lokalundersökningens ägarfält; blanketten avgör inte om Sara Britta hade juridisk deläganderätt."]]'::jsonb), true)->'story', '["Sara Brittas gårdskoppling till Valagården är etablerad genom hushållet med Bengt August Nilsson. Lokalundersökningen 1915 namnger bara Bengt i ägarfältet, så hennes eventuella juridiska andel lämnas uttryckligen öppen."]'::jsonb), true) where id = 'sara_britta_andersdotter';

